arguments.command:
cd /workspace/results/run100 && python3 -I -c "
import json
keys=None
vals={}
with open('metrics.jsonl') as f:
    for line in f:
        d=json.loads(line)
        if keys is None: keys=sorted(d.keys())
        for k,v in d.items():
            vals.setdefault(k,[]).append(v)
print(keys)
import re
for k in keys:
    if re.search('val|reward|trunc|len|clip|grad|entropy|kl|loss', k):
        xs=vals[k]
        print(k, 'n=',len(xs), 'first',xs[:3], 'last', xs[-3:])
"

